<template>
  <main class="paper-shell"><div class="paper-container institution-container"><header class="paper-workspace-header"><div><div class="paper-page-eyebrow">Knowledge Base / Institutions</div><h1 class="paper-page-title">Institution collaboration network</h1><p class="paper-page-description">Search institutions and inspect the original collaboration graph and paper counts.</p></div></header><LiteratureKnowledgeNav />
    <form class="paper-panel institution-search" @submit.prevent="load"><input v-model="affiliation" placeholder="Institution keyword; leave empty for global top institutions" /><button class="paper-button primary" :disabled="pending">Search</button><NuxtLink class="paper-button" :class="{disabled:!affiliation.trim()}" :to="{path:'/literature/authors',query:{affiliation}}">View scholars</NuxtLink></form><p v-if="error" class="notice">{{ error }}</p>
    <section class="paper-panel graph-panel"><div class="section-heading"><strong>Collaboration network</strong><span>{{ nodes.length }} institutions · {{ edges.length }} links</span></div><div ref="graph" class="institution-graph"><div class="empty">{{ pending?'Building network…':'No institution data.' }}</div></div></section>
    <section class="paper-panel list-panel"><div class="section-heading"><strong>Institution list</strong></div><table v-if="institutions.length"><thead><tr><th>Institution</th><th>Papers</th><th>Centre</th></tr></thead><tbody><tr v-for="item in institutions" :key="item.id" @click="select(item.label)"><td>{{ item.label }}</td><td>{{ item.paper_count||0 }}</td><td>{{ item.is_center?'Yes':'—' }}</td></tr></tbody></table><div v-else class="empty list-empty">No institution records.</div></section>
  </div></main>
</template>
<script setup>
import '~/assets/paper-platform.css';import LiteratureKnowledgeNav from '~/components/LiteratureKnowledgeNav.vue'
const config=useRuntimeConfig(),route=useRoute(),affiliation=ref(String(route.query.affiliation||'')),pending=ref(false),error=ref(''),graph=ref(null),nodes=ref([]),edges=ref([]);useHead({title:'Literature Institutions - OpenIsle'});const institutions=computed(()=>nodes.value.filter(n=>n.type==='institution'))
const chartLabels={'graph.paper':'Paper','graph.author':'Author','graph.keyword':'Keyword','graph.data_point':'Data point','graph.institution':'Institution','graph.no_nodes':'No institution data.','graph.controls.title':'Graph controls','graph.controls.toggle':'Toggle graph controls','graph.controls.relayout':'Rebuild layout','graph.controls.reset':'Reset view','graph.controls.show_all_labels':'Show all labels','graph.controls.smart_labels':'Use smart labels','graph.legend.upstream':'Upstream','graph.legend.downstream':'Downstream','graph.legend.two_hop':'Two-hop neighbour','tooltip.type':'Type','tooltip.year':'Year','tooltip.citations':'Citations','tooltip.connections':'Connections','tooltip.occurrences':'Occurrences','tooltip.paper_count':'Paper count','tooltip.click_focus':'Click to focus; double-click to open'}
const charts=async()=>{window.Utils=window.Utils||{truncate:(v,n)=>String(v||'').slice(0,n),escapeHtml:v=>String(v||'')};const previousTranslate=window.I18n?.t?.bind(window.I18n);window.I18n={...(window.I18n||{}),t:key=>chartLabels[key]||(previousTranslate?previousTranslate(key):key)};if(window.OpenIsleLiteratureCharts)return window.OpenIsleLiteratureCharts;await new Promise((ok,bad)=>{const s=document.createElement('script');s.src='/literature-engine/charts.js';s.onload=ok;s.onerror=bad;document.head.appendChild(s)});return window.OpenIsleLiteratureCharts}
const load=async()=>{pending.value=true;error.value='';try{const p=new URLSearchParams({max_nodes:'60',min_papers:'1'});if(affiliation.value.trim())p.set('affiliation',affiliation.value.trim());const data=await $fetch(`${config.public.apiBaseUrl}/api/literature/explore/institution/network?${p}`);nodes.value=data.nodes||[];edges.value=data.edges||[];const c=await charts();c.forceGraph(graph.value,nodes.value,edges.value,{show_labels:true,onNodeClick:n=>{if(n.type==='institution')select(n.label)}})}catch(cause){error.value=cause?.data?.message||cause?.message||'Unable to load institution network.'}finally{pending.value=false}};const select=name=>{affiliation.value=name;load()};onMounted(load)
</script>
<style scoped>
.institution-container{max-width:1180px}.institution-search{display:grid;grid-template-columns:1fr auto auto;gap:10px;padding:15px;margin-bottom:16px}.institution-search input{border:1px solid var(--paper-line);padding:9px 11px}.paper-button.disabled{pointer-events:none;opacity:.45}.graph-panel,.list-panel{overflow:hidden;margin-bottom:16px}.section-heading{display:flex;justify-content:space-between;padding:14px 18px;border-bottom:1px solid var(--paper-line)}.section-heading span{color:var(--paper-muted);font-size:11px}.institution-graph{position:relative;height:560px}.list-panel table{width:100%;border-collapse:collapse}.list-panel th,.list-panel td{padding:11px 15px;border-bottom:1px solid var(--paper-line);text-align:left;font-size:12px}.list-panel th{color:var(--paper-muted);font-size:10px;text-transform:uppercase}.list-panel tbody tr{cursor:pointer}.list-panel tbody tr:hover{background:#f5f9fa}.empty{display:grid;place-items:center;height:100%;color:var(--paper-muted)}.list-empty{min-height:100px}.notice{padding:10px 14px;background:#fff4f2;color:#8b3028}
</style>
